head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setUseFilterList]<br/>GridView 컴포넌트의 useFilterList 속성을 설정합니다.",
    "validation" : [
        "setUseFilterList() 메소드 실행 시 sortable=true, showSortableImage=true 이면 showSortableUseFilter 속성이 자동으로 true 로 설정됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  본 샘플은 @spec4(자동설정) 전용 : 그리드를 sortable=true & showSortableImage=true 로 고정 생성한다.
//  useFilterList / showSortableUseFilter 는 렌더 시 설정하지 않고, 동적 setUseFilterList 호출로만 변화를 확인한다.
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // sortable=true & showSortableImage=true 고정 (showSortableUseFilter 자동설정 전제조건)
    let properties = {
        sortable: true,
        showSortableImage: true
    };

    let lblDesc = '[전제] sortable=true, showSortableImage=true 고정 그리드 (col1~col3 = useFilter=true Header)'
        + '\n showSortableUseFilter / useFilterList 는 렌더 시 미설정(setUseFilterList 호출로만 확인).'
        + '\n[절차] par_filterList(true/false) 선택 후 (setUseFilterList) 버튼 실행.'
        + '\n[확인] flag 값과 무관하게 호출 후 options.showSortableUseFilter 가 자동으로 true 로 설정됨.';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="' + lblDesc + '"', '', 'label1');

    // GridView 바인딩용 body DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "col1": "서울", "col2": "노트북", "col3": "A", "col4": "재고" },
        { "col1": "부산", "col2": "모니터", "col3": "B", "col4": "재고" },
        { "col1": "서울", "col2": "키보드", "col3": "A", "col4": "판매" },
        { "col1": "대구", "col2": "마우스", "col3": "C", "col4": "판매" }
    ], false);

    let cList = $c.gcm.createCList(properties);
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    // useFilter="true" Header Column(col1~col3) + useFilter 미설정 Column(col4) 인라인 구성
    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' checkAllType="false" id="" dataList="data:dlt_bind" style="width:560px;height:280px;">';
    s += '<w2:caption style="" id="caption1" value="setUseFilterList 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="140" style="" inputType="text" id="hcol1" value="지역(useFilter)" useFilter="true"></w2:column>';
    s += '<w2:column width="140" style="" inputType="text" id="hcol2" value="품목(useFilter)" useFilter="true"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="hcol3" value="등급(useFilter)" useFilter="true"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="hcol4" value="상태(useFilter=false)"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="140" style="" inputType="text" id="col1" dataList="col1"></w2:column>';
    s += '<w2:column width="140" style="" inputType="text" id="col2" dataList="col2"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col3" dataList="col3"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="col4" dataList="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// [실행] setUseFilterList : sortable=true & showSortableImage=true 상태이면 flag 값과 무관하게
//  호출 후 options.showSortableUseFilter 가 자동으로 true 로 설정됨(@spec4).
scwin.btn_setUseFilterList_onclick = function () {
    // gdl_boolean 은 label('true'/'false') 로 판별 (value 는 2/3 이므로 getText 사용)
    let flag = (par_filterList.getText() === 'true');

    // 호출 전 값
    let before = target1.options.showSortableUseFilter;

    target1.setUseFilterList(flag);

    // 호출 후 값
    let after = target1.options.showSortableUseFilter;

    let msg = "setUseFilterList(" + flag + ") -> showSortableUseFilter : " + before + " (before) -> " + after + " (after)"
        + "\n / useFilterList : " + target1.options.useFilterList;
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
}
